DECLARE payload jsonb := $data$[{"language":"es","slug":"pastel-de-carne","public_path":"/es/receta/pastel-de-carne","title":"Pastel de carne estadounidense al horno","excerpt":"Un clásico meatloaf de res con cebolla y pan rallado, horneado con una cobertura de kétchup. Rinde ocho porciones y se corta después de un breve reposo.","summary":"Un clásico meatloaf de res con cebolla y pan rallado, horneado con una cobertura de kétchup. Rinde ocho porciones y se corta después de un breve reposo.","ingredients":[{"amount":"900","unit":"g","name":"carne molida de res con 15 % de grasa"},{"amount":"120","unit":"g","name":"cebolla blanca picada finamente"},{"amount":"10","unit":"g","name":"aceite de oliva"},{"amount":"80","unit":"g","name":"pan rallado seco"},{"amount":"100","unit":"ml","name":"leche entera"},{"amount":"2","unit":"unidad","name":"huevos grandes, aproximadamente 100 g sin cáscara"},{"amount":"100","unit":"g","name":"kétchup"},{"amount":"5","unit":"g","name":"sal"},{"amount":"1","unit":"g","name":"pimienta negra molida"}],"steps":[{"title":"Precalienta el horno","content":"Calienta el horno a 180 °C con calor arriba y abajo."},{"title":"Prepara la bandeja","content":"Forra una bandeja plana con papel para horno."},{"title":"Sofríe la cebolla","content":"Cocina la cebolla con el aceite a fuego medio durante 5 minutos, hasta que esté tierna.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Sofríe la cebolla"},{"title":"Enfría la cebolla","content":"Deja que la cebolla pierda el calor intenso."},{"title":"Mezcla la base","content":"Mezcla el pan rallado, la leche y los huevos en un bol grande."},{"title":"Añade la carne","content":"Incorpora la carne, la cebolla, la sal y la pimienta al bol."},{"title":"Une los ingredientes","content":"Mezcla suavemente solo hasta integrar; evita compactar la carne.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Une los ingredientes"},{"title":"Forma el pastel","content":"Forma un rectángulo de unos 25 × 10 cm sobre la bandeja preparada.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Forma el pastel"},{"title":"Extiende el kétchup","content":"Cubre la superficie del pastel con el kétchup.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Extiende el kétchup"},{"title":"Hornea el pastel","content":"Hornea unos 60 minutos, hasta que el centro alcance 71 °C medidos con termómetro.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Hornea el pastel"},{"title":"Deja reposar","content":"Deja reposar el pastel 10 minutos fuera del horno."},{"title":"Corta las porciones","content":"Corta el pastel en ocho rebanadas."},{"title":"Sirve","content":"Sirve las rebanadas calientes.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Sirve"}],"seo":{"title":"Pastel de carne estadounidense al horno | Meatloaf casero","description":"Prepara un pastel de carne de res al horno con cebolla y cobertura de kétchup. Incluye tiempos, temperatura de cocción y consejos para cortarlo.","image_alt":"Pastel de carne estadounidense al horno","faq":[{"q":"¿Cómo evito que quede duro?","a":"Mezcla lo justo para unir los ingredientes y forma el pastel sin apretar demasiado."},{"q":"¿Cómo sé que está cocido?","a":"Introduce un termómetro en el centro: la carne molida debe alcanzar 71 °C."},{"q":"¿Puedo prepararlo con anticipación?","a":"Puedes darle forma, refrigerarlo bien tapado y hornearlo al día siguiente. Comprueba siempre la temperatura central."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"1 de 8 porciones","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Estimación sin acompañamientos; no descuenta la grasa que pueda quedar en la bandeja. Los valores dependen de la carne, el pan rallado y el kétchup."},"notes":"<p>No pruebes la mezcla cruda. Lávate las manos y limpia los utensilios después de manipular carne cruda. La temperatura interna es más fiable que el color; si no llega a 71 °C, prolonga la cocción. El reposo ayuda a cortar sin deshacer el pastel. Refrigera las sobras dentro de las dos horas siguientes.</p>","category":"Platos principales","cuisine":"Estadounidense","difficulty":"Fácil","course":"Plato principal","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Pastel de carne estadounidense al horno"],"content_html":""},{"language":"de","slug":"amerikanischer-hackbraten-aus-dem-ofen","public_path":"/de/amerikanischer-hackbraten-aus-dem-ofen","title":"Amerikanischer Hackbraten aus dem Ofen","excerpt":"Klassischer Hackbraten aus Rindfleisch mit Zwiebel, Semmelbröseln und Ketchupglasur. Vor dem Anschneiden ruht er zehn Minuten.","summary":"Klassischer Hackbraten aus Rindfleisch mit Zwiebel, Semmelbröseln und Ketchupglasur. Vor dem Anschneiden ruht er zehn Minuten.","ingredients":[{"amount":"900","unit":"g","name":"Rinderhackfleisch mit 15 % Fett"},{"amount":"120","unit":"g","name":"weiße Zwiebel, fein gehackt"},{"amount":"10","unit":"g","name":"Olivenöl"},{"amount":"80","unit":"g","name":"einfache trockene Semmelbrösel"},{"amount":"100","unit":"ml","name":"Vollmilch"},{"amount":"2","unit":"Stück","name":"große Eier, etwa 100 g ohne Schale"},{"amount":"100","unit":"g","name":"Ketchup"},{"amount":"5","unit":"g","name":"Salz"},{"amount":"1","unit":"g","name":"schwarzer Pfeffer, gemahlen"}],"steps":[{"title":"Ofen vorheizen","content":"Den Backofen auf 180 °C Ober- und Unterhitze vorheizen."},{"title":"Blech vorbereiten","content":"Ein flaches Backblech mit Backpapier belegen."},{"title":"Zwiebel garen","content":"Die Zwiebel im Öl bei mittlerer Hitze 5 Minuten weich garen.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Zwiebel garen"},{"title":"Zwiebel abkühlen","content":"Die Zwiebel abkühlen lassen, bis sie nicht mehr heiß ist."},{"title":"Grundmasse mischen","content":"Semmelbrösel, Milch und Eier in einer großen Schüssel mischen."},{"title":"Fleisch zugeben","content":"Hackfleisch, Zwiebel, Salz und Pfeffer in die Schüssel geben."},{"title":"Vorsichtig mischen","content":"Nur kurz vermengen, ohne die Masse fest zu drücken.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Vorsichtig mischen"},{"title":"Braten formen","content":"Auf dem vorbereiteten Blech ein etwa 25 × 10 cm großes Rechteck formen.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Braten formen"},{"title":"Ketchup verstreichen","content":"Die Oberfläche mit Ketchup bestreichen.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Ketchup verstreichen"},{"title":"Hackbraten backen","content":"Etwa 60 Minuten backen, bis die Mitte auf dem Thermometer 71 °C erreicht.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Hackbraten backen"},{"title":"Ruhen lassen","content":"Den Braten außerhalb des Ofens 10 Minuten ruhen lassen."},{"title":"Portionen schneiden","content":"Den Braten in acht Scheiben schneiden."},{"title":"Servieren","content":"Die Scheiben warm servieren.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Servieren"}],"seo":{"title":"Amerikanischer Hackbraten aus dem Ofen","description":"Klassischer Hackbraten aus Rindfleisch mit Zwiebel, Semmelbröseln und Ketchupglasur. Vor dem Anschneiden ruht er zehn Minuten.","image_alt":"Amerikanischer Hackbraten aus dem Ofen","faq":[{"q":"Wie bleibt Hackbraten zart?","a":"Nur kurz vermengen und beim Formen nicht stark zusammendrücken."},{"q":"Woran erkenne ich, dass er gar ist?","a":"Die Mitte mit einem Thermometer messen: Rinderhack muss 71 °C erreichen."},{"q":"Kann ich ihn vorbereiten?","a":"Geformt und gut abgedeckt bis zum nächsten Tag kühlen, dann backen und die Kerntemperatur prüfen."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"Ein Achtel des Hackbratens","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Schätzung ohne Beilagen; ausgetretenes Fett wird nicht abgezogen. Die Produkte können abweichen."},"notes":"<p>Die rohe Masse nicht probieren. Hände und Geräte nach Kontakt mit rohem Fleisch waschen. Falls die Mitte unter 71 °C liegt, länger backen. Die Ruhezeit erleichtert das Schneiden. Reste innerhalb von zwei Stunden kühlen.</p>","category":"Hauptgerichte","cuisine":"Amerikanisch","difficulty":"Einfach","course":"Hauptgericht","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Amerikanischer Hackbraten aus dem Ofen"],"content_html":""},{"language":"en","slug":"classic-american-meatloaf","public_path":"/en/classic-american-meatloaf","title":"Classic American meatloaf","excerpt":"A classic beef meatloaf with onion, breadcrumbs and a ketchup glaze, baked and rested before slicing into eight portions.","summary":"A classic beef meatloaf with onion, breadcrumbs and a ketchup glaze, baked and rested before slicing into eight portions.","ingredients":[{"amount":"900","unit":"g","name":"ground beef, 85% lean"},{"amount":"120","unit":"g","name":"white onion, finely chopped"},{"amount":"10","unit":"g","name":"olive oil"},{"amount":"80","unit":"g","name":"plain dry breadcrumbs"},{"amount":"100","unit":"ml","name":"whole milk"},{"amount":"2","unit":"piece","name":"large eggs, about 100 g without shells"},{"amount":"100","unit":"g","name":"ketchup"},{"amount":"5","unit":"g","name":"salt"},{"amount":"1","unit":"g","name":"ground black pepper"}],"steps":[{"title":"Preheat the oven","content":"Heat the oven to 180 °C (350 °F), conventional setting."},{"title":"Prepare the tray","content":"Line a flat baking tray with parchment."},{"title":"Cook the onion","content":"Cook the onion in the oil over medium heat for 5 minutes, until soft.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Cook the onion"},{"title":"Cool the onion","content":"Let the onion cool until no longer hot."},{"title":"Mix the base","content":"Mix the breadcrumbs, milk and eggs in a large bowl."},{"title":"Add the beef","content":"Add the beef, onion, salt and pepper to the bowl."},{"title":"Combine gently","content":"Mix gently just until combined; do not compact the meat.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Combine gently"},{"title":"Shape the loaf","content":"Shape into a rectangle about 25 × 10 cm on the prepared tray.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Shape the loaf"},{"title":"Spread the ketchup","content":"Cover the top of the loaf with ketchup.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Spread the ketchup"},{"title":"Bake the loaf","content":"Bake for about 60 minutes, until the centre reaches 71 °C (160 °F) on a thermometer.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Bake the loaf"},{"title":"Let it rest","content":"Rest the loaf out of the oven for 10 minutes."},{"title":"Cut the portions","content":"Cut into eight slices."},{"title":"Serve","content":"Serve the slices warm.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Serve"}],"seo":{"title":"Classic American meatloaf","description":"A classic beef meatloaf with onion, breadcrumbs and a ketchup glaze, baked and rested before slicing into eight portions.","image_alt":"Classic American meatloaf","faq":[{"q":"How do I keep meatloaf tender?","a":"Mix only until combined and shape without pressing firmly."},{"q":"How can I tell it is cooked?","a":"Use a thermometer in the centre; ground beef must reach 71 °C (160 °F)."},{"q":"Can I prepare it ahead?","a":"Shape it and refrigerate covered until the next day, then bake and check the centre temperature."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"One eighth of the loaf","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Estimate without side dishes; fat left in the pan is not deducted. Ingredients and brands vary."},"notes":"<p>Do not taste the raw mixture. Wash hands and utensils after handling raw meat. If the centre is below 71 °C, cook longer. The rest makes slicing easier. Refrigerate leftovers within two hours.</p>","category":"Main dishes","cuisine":"American","difficulty":"Easy","course":"Main course","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Classic American meatloaf"],"content_html":""},{"language":"fr","slug":"pain-de-viande-americain-au-four","public_path":"/fr/pain-de-viande-americain-au-four","title":"Pain de viande américain au four","excerpt":"Un pain de viande de bœuf à l’oignon et à la chapelure, nappé de ketchup. Il repose avant d’être coupé en huit portions.","summary":"Un pain de viande de bœuf à l’oignon et à la chapelure, nappé de ketchup. Il repose avant d’être coupé en huit portions.","ingredients":[{"amount":"900","unit":"g","name":"bœuf haché à 15 % de matière grasse"},{"amount":"120","unit":"g","name":"oignon blanc finement haché"},{"amount":"10","unit":"g","name":"huile d’olive"},{"amount":"80","unit":"g","name":"chapelure nature sèche"},{"amount":"100","unit":"ml","name":"lait entier"},{"amount":"2","unit":"unité","name":"gros œufs, environ 100 g sans coquille"},{"amount":"100","unit":"g","name":"ketchup"},{"amount":"5","unit":"g","name":"sel"},{"amount":"1","unit":"g","name":"poivre noir moulu"}],"steps":[{"title":"Préchauffez le four","content":"Chauffez le four à 180 °C en chaleur traditionnelle."},{"title":"Préparez la plaque","content":"Tapissez une plaque plate de papier cuisson."},{"title":"Cuisez l’oignon","content":"Faites cuire l’oignon dans l’huile à feu moyen pendant 5 minutes, jusqu’à ce qu’il soit tendre.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Cuisez l’oignon"},{"title":"Refroidissez l’oignon","content":"Laissez l’oignon perdre sa forte chaleur."},{"title":"Mélangez la base","content":"Mélangez la chapelure, le lait et les œufs dans un grand saladier."},{"title":"Ajoutez la viande","content":"Ajoutez le bœuf, l’oignon, le sel et le poivre dans le saladier."},{"title":"Mélangez doucement","content":"Mélangez juste assez pour incorporer les ingrédients sans tasser.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Mélangez doucement"},{"title":"Façonnez le pain","content":"Formez un rectangle d’environ 25 × 10 cm sur la plaque préparée.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Façonnez le pain"},{"title":"Étalez le ketchup","content":"Recouvrez le dessus de ketchup.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Étalez le ketchup"},{"title":"Enfournez","content":"Faites cuire environ 60 minutes, jusqu’à 71 °C à cœur au thermomètre.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Enfournez"},{"title":"Laissez reposer","content":"Laissez reposer hors du four pendant 10 minutes."},{"title":"Coupez les portions","content":"Coupez le pain de viande en huit tranches."},{"title":"Servez","content":"Servez les tranches chaudes.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Servez"}],"seo":{"title":"Pain de viande américain au four","description":"Un pain de viande de bœuf à l’oignon et à la chapelure, nappé de ketchup. Il repose avant d’être coupé en huit portions.","image_alt":"Pain de viande américain au four","faq":[{"q":"Comment éviter un pain de viande dur ?","a":"Mélangez juste assez pour incorporer les ingrédients et façonnez sans tasser."},{"q":"Comment vérifier la cuisson ?","a":"Mesurez au centre avec un thermomètre : le bœuf haché doit atteindre 71 °C."},{"q":"Puis-je le préparer à l’avance ?","a":"Façonnez-le et réfrigérez-le bien couvert jusqu’au lendemain, puis cuisez-le en vérifiant la température."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"Un huitième du pain de viande","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Estimation sans accompagnement et sans déduire la graisse restée sur la plaque. Les produits varient."},"notes":"<p>Ne goûtez pas la préparation crue. Lavez les mains et les ustensiles après contact avec la viande crue. Prolongez la cuisson si le centre n’atteint pas 71 °C. Le repos facilite la découpe. Réfrigérez les restes dans les deux heures.</p>","category":"Plats principaux","cuisine":"Américaine","difficulty":"Facile","course":"Plat principal","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Pain de viande américain au four"],"content_html":""},{"language":"it","slug":"polpettone-americano-al-forno","public_path":"/it/polpettone-americano-al-forno","title":"Polpettone americano al forno","excerpt":"Un classico polpettone di manzo con cipolla e pangrattato, cotto con una glassa al ketchup e lasciato riposare prima del taglio.","summary":"Un classico polpettone di manzo con cipolla e pangrattato, cotto con una glassa al ketchup e lasciato riposare prima del taglio.","ingredients":[{"amount":"900","unit":"g","name":"manzo macinato con 15% di grasso"},{"amount":"120","unit":"g","name":"cipolla bianca tritata finemente"},{"amount":"10","unit":"g","name":"olio d’oliva"},{"amount":"80","unit":"g","name":"pangrattato secco semplice"},{"amount":"100","unit":"ml","name":"latte intero"},{"amount":"2","unit":"pezzo","name":"uova grandi, circa 100 g senza guscio"},{"amount":"100","unit":"g","name":"ketchup"},{"amount":"5","unit":"g","name":"sale"},{"amount":"1","unit":"g","name":"pepe nero macinato"}],"steps":[{"title":"Scalda il forno","content":"Porta il forno statico a 180 °C."},{"title":"Prepara la teglia","content":"Rivesti una teglia piana con carta forno."},{"title":"Cuoci la cipolla","content":"Cuoci la cipolla nell’olio a fuoco medio per 5 minuti, finché morbida.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Cuoci la cipolla"},{"title":"Raffredda la cipolla","content":"Lascia intiepidire la cipolla."},{"title":"Mescola la base","content":"Mescola pangrattato, latte e uova in una ciotola grande."},{"title":"Aggiungi la carne","content":"Unisci manzo, cipolla, sale e pepe alla ciotola."},{"title":"Amalgama delicatamente","content":"Mescola solo fino a incorporare, senza pressare la carne.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Amalgama delicatamente"},{"title":"Forma il polpettone","content":"Forma un rettangolo di circa 25 × 10 cm sulla teglia preparata.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Forma il polpettone"},{"title":"Spalma il ketchup","content":"Copri la superficie con il ketchup.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Spalma il ketchup"},{"title":"Cuoci in forno","content":"Cuoci per circa 60 minuti, fino a 71 °C al centro misurati con un termometro.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Cuoci in forno"},{"title":"Lascia riposare","content":"Lascia riposare fuori dal forno per 10 minuti."},{"title":"Taglia le porzioni","content":"Taglia il polpettone in otto fette."},{"title":"Servi","content":"Servi le fette calde.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Servi"}],"seo":{"title":"Polpettone americano al forno","description":"Un classico polpettone di manzo con cipolla e pangrattato, cotto con una glassa al ketchup e lasciato riposare prima del taglio.","image_alt":"Polpettone americano al forno","faq":[{"q":"Come evitare che sia duro?","a":"Amalgama solo il necessario e non comprimere troppo la carne."},{"q":"Come verifico la cottura?","a":"Misura il centro con un termometro: il manzo macinato deve raggiungere 71 °C."},{"q":"Posso prepararlo in anticipo?","a":"Conservalo già formato e ben coperto in frigorifero fino al giorno dopo, poi cuocilo e misura il centro."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"Un ottavo del polpettone","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Stima senza contorni e senza sottrarre il grasso rimasto nella teglia. I valori variano secondo i prodotti."},"notes":"<p>Non assaggiare il composto crudo. Lava mani e utensili dopo il contatto con la carne cruda. Se il centro non raggiunge 71 °C, prolunga la cottura. Il riposo facilita il taglio. Refrigera gli avanzi entro due ore.</p>","category":"Secondi piatti","cuisine":"Statunitense","difficulty":"Facile","course":"Secondo","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Polpettone americano al forno"],"content_html":""},{"language":"ja","slug":"amerika-fu-meatloaf","public_path":"/ja/amerika-fu-meatloaf","title":"アメリカ風ミートローフ","excerpt":"玉ねぎとパン粉を混ぜた牛ひき肉にケチャップを塗って焼く、アメリカの定番ミートローフ。休ませてから8人分に切ります。","summary":"玉ねぎとパン粉を混ぜた牛ひき肉にケチャップを塗って焼く、アメリカの定番ミートローフ。休ませてから8人分に切ります。","ingredients":[{"amount":"900","unit":"g","name":"脂肪分15％の牛ひき肉"},{"amount":"120","unit":"g","name":"みじん切りの白玉ねぎ"},{"amount":"10","unit":"g","name":"オリーブオイル"},{"amount":"80","unit":"g","name":"乾燥パン粉"},{"amount":"100","unit":"ml","name":"牛乳（全脂）"},{"amount":"2","unit":"個","name":"大きな卵（殻を除いて約100 g）"},{"amount":"100","unit":"g","name":"ケチャップ"},{"amount":"5","unit":"g","name":"塩"},{"amount":"1","unit":"g","name":"黒こしょう"}],"steps":[{"title":"オーブンを予熱する","content":"オーブンを180 °Cに予熱します。"},{"title":"天板を用意する","content":"平らな天板にオーブンシートを敷きます。"},{"title":"玉ねぎを炒める","content":"玉ねぎを油で中火で5分、柔らかくなるまで炒めます。","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"玉ねぎを炒める"},{"title":"玉ねぎを冷ます","content":"玉ねぎの粗熱を取ります。"},{"title":"下地を混ぜる","content":"大きなボウルでパン粉、牛乳、卵を混ぜます。"},{"title":"ひき肉を加える","content":"牛ひき肉、玉ねぎ、塩、こしょうをボウルに加えます。"},{"title":"優しく混ぜる","content":"肉を押し固めず、全体がなじむまで軽く混ぜます。","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"優しく混ぜる"},{"title":"形を整える","content":"用意した天板の上で約25 × 10 cmの長方形に形を整えます。","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"形を整える"},{"title":"ケチャップを塗る","content":"表面にケチャップを塗ります。","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"ケチャップを塗る"},{"title":"オーブンで焼く","content":"約60分焼き、中心温度が温度計で71 °Cに達するまで加熱します。","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"オーブンで焼く"},{"title":"休ませる","content":"オーブンから出して10分休ませます。"},{"title":"切り分ける","content":"8枚に切り分けます。"},{"title":"盛り付ける","content":"温かいうちに盛り付けます。","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"盛り付ける"}],"seo":{"title":"アメリカ風ミートローフ","description":"玉ねぎとパン粉を混ぜた牛ひき肉にケチャップを塗って焼く、アメリカの定番ミートローフ。休ませてから8人分に切ります。","image_alt":"アメリカ風ミートローフ","faq":[{"q":"硬くしないコツは？","a":"混ぜすぎず、強く押し固めずに形を整えます。"},{"q":"火が通ったかどうかは？","a":"中心を温度計で測り、牛ひき肉の中心が71 °Cに達したことを確認します。"},{"q":"前日に準備できますか？","a":"成形後にしっかり覆って翌日まで冷蔵し、焼くときに中心温度を確認します。"}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"全体の8分の1","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"付け合わせを除く推定値です。天板に残る脂は差し引いていません。材料により数値は変わります。"},"notes":"<p>生のたねは味見しないでください。生肉に触れた手や器具は洗います。中心が71 °C未満なら追加で加熱します。休ませると切りやすくなります。残りは2時間以内に冷蔵します。</p>","category":"主菜","cuisine":"アメリカ料理","difficulty":"簡単","course":"主菜","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["アメリカ風ミートローフ"],"content_html":""},{"language":"pt","slug":"bolo-de-carne-americano-assado","public_path":"/pt/bolo-de-carne-americano-assado","title":"Bolo de carne americano assado","excerpt":"Um clássico bolo de carne bovina com cebola, farinha de rosca e cobertura de ketchup. Rende oito porções e descansa antes de cortar.","summary":"Um clássico bolo de carne bovina com cebola, farinha de rosca e cobertura de ketchup. Rende oito porções e descansa antes de cortar.","ingredients":[{"amount":"900","unit":"g","name":"carne bovina moída com 15% de gordura"},{"amount":"120","unit":"g","name":"cebola branca picada finamente"},{"amount":"10","unit":"g","name":"azeite de oliva"},{"amount":"80","unit":"g","name":"farinha de rosca simples"},{"amount":"100","unit":"ml","name":"leite integral"},{"amount":"2","unit":"unidade","name":"ovos grandes, cerca de 100 g sem casca"},{"amount":"100","unit":"g","name":"ketchup"},{"amount":"5","unit":"g","name":"sal"},{"amount":"1","unit":"g","name":"pimenta-do-reino moída"}],"steps":[{"title":"Aqueça o forno","content":"Aqueça o forno a 180 °C, com calor superior e inferior."},{"title":"Prepare a assadeira","content":"Forre uma assadeira plana com papel-manteiga."},{"title":"Refogue a cebola","content":"Cozinhe a cebola no azeite em fogo médio por 5 minutos, até ficar macia.","image_url":"/recetas/pastel-de-carne-americano/paso-03.webp","image_alt":"Refogue a cebola"},{"title":"Esfrie a cebola","content":"Deixe a cebola perder o calor intenso."},{"title":"Misture a base","content":"Misture a farinha de rosca, o leite e os ovos numa tigela grande."},{"title":"Adicione a carne","content":"Junte carne, cebola, sal e pimenta à tigela."},{"title":"Misture delicadamente","content":"Misture apenas até integrar, sem compactar a carne.","image_url":"/recetas/pastel-de-carne-americano/paso-07.webp","image_alt":"Misture delicadamente"},{"title":"Modele o bolo","content":"Modele um retângulo de cerca de 25 × 10 cm na assadeira preparada.","image_url":"/recetas/pastel-de-carne-americano/paso-08.webp","image_alt":"Modele o bolo"},{"title":"Espalhe o ketchup","content":"Cubra a superfície do bolo com ketchup.","image_url":"/recetas/pastel-de-carne-americano/paso-09.webp","image_alt":"Espalhe o ketchup"},{"title":"Asse o bolo","content":"Asse por cerca de 60 minutos, até o centro atingir 71 °C no termômetro.","image_url":"/recetas/pastel-de-carne-americano/paso-10.webp","image_alt":"Asse o bolo"},{"title":"Deixe descansar","content":"Deixe descansar fora do forno por 10 minutos."},{"title":"Corte as porções","content":"Corte o bolo em oito fatias."},{"title":"Sirva","content":"Sirva as fatias quentes.","image_url":"/recetas/pastel-de-carne-americano/portada.webp","image_alt":"Sirva"}],"seo":{"title":"Bolo de carne americano assado","description":"Um clássico bolo de carne bovina com cebola, farinha de rosca e cobertura de ketchup. Rende oito porções e descansa antes de cortar.","image_alt":"Bolo de carne americano assado","faq":[{"q":"Como evitar que fique duro?","a":"Misture apenas até incorporar e modele sem apertar."},{"q":"Como saber se está cozido?","a":"Meça o centro com termômetro: a carne moída deve atingir 71 °C."},{"q":"Posso preparar antes?","a":"Modele e refrigere bem coberto até o dia seguinte; asse e confira a temperatura central."}],"image_variants":["/recetas/pastel-de-carne-americano/portada-1x1.webp","/recetas/pastel-de-carne-americano/portada-4x3.webp","/recetas/pastel-de-carne-americano/portada-16x9.webp"]},"nutrition":{"calories":336.9,"protein_g":24.5,"carbs_g":12.8,"fat_g":20.3,"serving_size":"Uma de oito porções","estimated":true,"source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes crudos dividida entre ocho; los 100 ml de leche se aproximan a 100 g.","note":"Estimativa sem acompanhamentos e sem descontar a gordura que ficar na assadeira. Os produtos variam."},"notes":"<p>Não prove a mistura crua. Lave mãos e utensílios após tocar a carne crua. Se o centro não atingir 71 °C, asse mais. O descanso facilita o corte. Refrigere sobras em até duas horas.</p>","category":"Pratos principais","cuisine":"Americana","difficulty":"Fácil","course":"Prato principal","prep_time_minutes":20,"cook_time_minutes":65,"total_time_minutes":95,"servings":8,"image_url":"/recetas/pastel-de-carne-americano/portada.webp","keywords":["Bolo de carne americano assado"],"content_html":""}]$data$::jsonb; n integer;
BEGIN
 PERFORM 1 FROM public.recipes WHERE recipe_group_id='e7364c1c-74b1-4a10-b8d6-451024485b6e' FOR UPDATE;
