 IF EXISTS (SELECT 1 FROM public.recipes WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x WHERE x->>'language'<>'es')) OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x WHERE x->>'language'<>'es')) THEN RAISE EXCEPTION 'Colisión de URL'; END IF;
