 INSERT INTO public.recipes (recipe_group_id,language,slug, title, excerpt, ingredients, steps, category, prep_time_minutes, cook_time_minutes, servings, image_url, content_html, summary, notes, difficulty, course, cuisine, total_time_minutes, keywords, nutrition, seo, public_path,published,editorial_status) SELECT 'e7364c1c-74b1-4a10-b8d6-451024485b6e'::uuid,s.language,s.slug, s.title, s.excerpt, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.servings, s.image_url, s.content_html, s.summary, s.notes, s.difficulty, s.course, s.cuisine, s.total_time_minutes, s.keywords, s.nutrition, s.seo, s.public_path,true,'published' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 DELETE FROM public.content_redirects WHERE source_path='/es/receta/pastel-de-carne' AND status_code IN (302,307);
 SELECT count(DISTINCT language) INTO n FROM public.recipes WHERE recipe_group_id='e7364c1c-74b1-4a10-b8d6-451024485b6e' AND published=true AND nutrition IS NOT NULL;
